  slide.addText(label, {
    x: x + 0.14, y: y + h * 0.55, w: w - 0.2, h: h * 0.42,
    fontSize: 10, color: C.midGray, fontFace: "Calibri",
    valign: "top", align: "left", margin: 0
  });
}

