      dataLabelFontSize: 9,
      showLegend: false,
      valAxisTitle: "Tonnes CO₂ per person",
      showValAxisTitle: true,
      valAxisTitleColor: C.midGray,
      valAxisTitleFontSize: 9,
    });

    // Key callout
    const cx = 7.05;
    s.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: 0.82, w: 2.6, h: 1.85,
      fill: { color: C.dark }, line: { color: C.dark },
      shadow: mkShadow()
    });
    s.addText([
      { text: "150×\n", options: { fontSize: 36, bold: true, color: C.amber, breakLine: false } },
      { text: "gap", options: { fontSize: 24, bold: true, color: C.white } },
      { text: "\nbetween Chad (0.1 t) and US/Canada (~14 t)", options: { fontSize: 9.5, color: "9BBCD6" } }
    ], {
      x: cx, y: 0.82, w: 2.6, h: 1.85,
      fontFace: "Calibri", align: "center", valign: "middle", margin: 10
    });

    // Insight box
    s.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: 2.82, w: 2.6, h: 2.42,
      fill: { color: C.white }, line: { color: C.ltGray, width: 1 },
      shadow: mkShadow()
    });
    s.addShape(pres.shapes.RECTANGLE, { x: cx, y: 2.82, w: 0.06, h: 2.42, fill: { color: C.amber }, line: { color: C.amber } });
    s.addText([
      { text: "Prosperity ≠ high emissions\n\n", options: { bold: true, fontSize: 11, color: C.charcoal, breakLine: false } },
      { text: "France, UK & Portugal emit far less than Germany or the US despite similar living standards — thanks to nuclear and renewable energy.", options: { fontSize: 10, color: C.charcoal } }
    ], {
      x: cx + 0.14, y: 2.88, w: 2.44, h: 2.3,
      fontFace: "Calibri", align: "left", valign: "top", margin: 6
    });
  }

  // ── SLIDE 6 – Per Capita Snapshot (detailed bar chart) ──────────────────
  {
    const s = pres.addSlide();
    s.background = { color: C.offWht };
    addHeader(s, pres, "Per Capita Emissions Vary Widely: ~14 t in the US vs. ~9 t in China and ~2 t in India");
    addFooter(s, pres);

    // Use figure_8 image on right + bar chart on left
    const countries = ["Kenya","India","UK","World avg","EU-27","South Africa","China","Canada","United States"];
    const values    = [0.4,  2.0,  4.0,  4.5,   6.0,   7.0,     9.0,    14.0,  14.0];

    s.addChart(pres.charts.BAR, [
      { name: "Per capita CO₂ (t/person/yr, 2024)", labels: countries, values: values }
    ], {
      x: 0.35, y: 0.85, w: 5.8, h: 4.4,
      barDir: "bar",
      chartColors: [C.tealLt, C.tealLt, C.midGray, C.midGray, "2E86C1", C.amber, C.amber, C.red, C.red],
      chartArea: { fill: { color: C.offWht } },
      plotArea: { fill: { color: C.offWht } },
      catAxisLabelColor: C.charcoal,
      valAxisLabelColor: C.midGray,
      catAxisLabelFontSize: 9,
      valAxisLabelFontSize: 9,
      valGridLine: { color: C.ltGray, size: 0.5 },
      catGridLine: { style: "none" },
      showValue: true,
      dataLabelFormatCode: '0.0',
      dataLabelColor: C.charcoal,
      dataLabelFontSize: 9,
      showLegend: false,
    });

    // figure_8 image inset
    s.addShape(pres.shapes.RECTANGLE, {
      x: 6.3, y: 0.85, w: 3.35, h: 2.5,
      fill: { color: C.white }, line: { color: C.ltGray, width: 1 },
      shadow: mkShadow()
    });
    s.addImage({
      path: path.join(ASSETS, "figure_8.jpg"),
      x: 6.35, y: 0.9, w: 3.25, h: 2.38,
      sizing: { type: "contain", w: 3.25, h: 2.38 }
    });

    // Key insight
    s.addShape(pres.shapes.RECTANGLE, {
      x: 6.3, y: 3.48, w: 3.35, h: 1.77,
      fill: { color: C.navy }, line: { color: C.navy },
      shadow: mkShadow()
    });
    s.addText([
      { text: "China is the #1 total emitter\n", options: { bold: true, color: C.tealLt, fontSize: 12 } },
      { text: "yet its per capita (9 t) is well below the US (14 t) and Canada (14 t) — and only 2× the world average.", options: { color: C.white, fontSize: 10 } }
    ], {
      x: 6.3, y: 3.48, w: 3.35, h: 1.77,
      fontFace: "Calibri", align: "left", valign: "middle", margin: 12
    });
  }

  // ── SLIDE 7 – 2024 Annual Change ─────────────────────────────────────────
  {
    const s = pres.addSlide();
    s.background = { color: C.offWht };
    addHeader(s, pres, "2024 Snapshot: Many Western Nations Cut Emissions While Parts of Asia and Africa Grew");
    addFooter(s, pres);

    // Map image (figure_5)
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.35, y: 0.85, w: 6.0, h: 3.85,
      fill: { color: C.white }, line: { color: C.ltGray, width: 1 },
      shadow: mkShadow()
    });
    s.addImage({
      path: path.join(ASSETS, "figure_5.jpg"),
      x: 0.4, y: 0.9, w: 5.9, h: 3.73,
      sizing: { type: "contain", w: 5.9, h: 3.73 }
    });
    s.addText("Annual % change in CO₂ emissions, 2024  ·  Blue = decrease  ·  Red/Orange = increase", {
      x: 0.35, y: 4.72, w: 6.0, h: 0.25,
      fontSize: 8, color: C.midGray, fontFace: "Calibri", italic: true, align: "center", margin: 0
    });

    // Right panel
    const px = 6.55;
    s.addShape(pres.shapes.RECTANGLE, {
      x: px, y: 0.85, w: 3.1, h: 4.4,
      fill: { color: C.white }, line: { color: C.ltGray, width: 1 },
      shadow: mkShadow()
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: px, y: 0.85, w: 3.1, h: 0.42,
      fill: { color: C.navy }, line: { color: C.navy }
    });
    s.addText("2024 WINNERS & LAGGARDS", {
      x: px + 0.08, y: 0.85, w: 2.94, h: 0.42,
      fontSize: 10, bold: true, color: C.white, fontFace: "Calibri",
      align: "center", valign: "middle", margin: 0
    });

    // Decreases
    s.addShape(pres.shapes.RECTANGLE, {
      x: px + 0.12, y: 1.38, w: 2.86, h: 0.28,
      fill: { color: "EBF5FB" }, line: { color: "2E86C1", width: 1 }
    });
    s.addText("DECREASED", {
      x: px + 0.12, y: 1.38, w: 2.86, h: 0.28,
      fontSize: 9, bold: true, color: "2E86C1", fontFace: "Calibri",
      align: "center", valign: "middle", margin: 0
    });
    const decreasers = ["United States", "European Union", "United Kingdom", "Germany", "Japan"];
    decreasers.forEach((c, i) => {
      s.addText([
        { text: "↓  ", options: { color: "2E86C1", bold: true } },
        { text: c, options: { color: C.charcoal } }
      ], {
        x: px + 0.18, y: 1.72 + i * 0.32, w: 2.78, h: 0.28,
        fontSize: 10, fontFace: "Calibri", align: "left", margin: 0
      });
    });

    // Increases
    s.addShape(pres.shapes.RECTANGLE, {
      x: px + 0.12, y: 3.42, w: 2.86, h: 0.28,
      fill: { color: "FDEDEC" }, line: { color: C.red, width: 1 }
    });
    s.addText("INCREASED", {
      x: px + 0.12, y: 3.42, w: 2.86, h: 0.28,
      fontSize: 9, bold: true, color: C.red, fontFace: "Calibri",
      align: "center", valign: "middle", margin: 0
    });
    const increasers = ["Russia", "SE Asia (parts)", "Central Asia (>10%)", "Parts of Africa"];
    increasers.forEach((c, i) => {
      s.addText([
        { text: "↑  ", options: { color: C.red, bold: true } },
        { text: c, options: { color: C.charcoal } }
      ], {
        x: px + 0.18, y: 3.76 + i * 0.32, w: 2.78, h: 0.28,
        fontSize: 10, fontFace: "Calibri", align: "left", margin: 0
      });
    });
  }

  // ── SLIDE 8 – Energy Mix Matters ─────────────────────────────────────────
  {
    const s = pres.addSlide();
    s.background = { color: C.offWht };
    addHeader(s, pres, "Energy Mix Explains Why France and the UK Emit Far Less Per Capita Than Germany or the US");
    addFooter(s, pres);

    // Comparative bar chart for per capita among wealthy peers
    const nations = ["France","UK","Portugal","EU-27 avg","Germany","Netherlands","United States"];
    const pcVals  = [4.5,    4.0,  3.5,     6.0,     8.0,     9.0,         14.0];
    const colors  = [C.teal, C.teal, C.teal, "2E86C1", C.amber, C.amber, C.red];

    s.addChart(pres.charts.BAR, [
      { name: "Per capita CO₂ t/person (2024)", labels: nations, values: pcVals }
    ], {
      x: 0.35, y: 0.85, w: 5.8, h: 4.42,
      barDir: "bar",
      chartColors: colors,
      chartArea: { fill: { color: C.offWht } },
      plotArea: { fill: { color: C.offWht } },
      catAxisLabelColor: C.charcoal,
      valAxisLabelColor: C.midGray,
      catAxisLabelFontSize: 10,
      valAxisLabelFontSize: 9,
      valGridLine: { color: C.ltGray, size: 0.5 },
      catGridLine: { style: "none" },
      showValue: true,
      dataLabelFormatCode: '0.0',
      dataLabelColor: C.charcoal,
      dataLabelFontSize: 9,
      showLegend: false,
      valAxisTitle: "Tonnes CO₂ per person",
      showValAxisTitle: true,
      valAxisTitleColor: C.midGray,
      valAxisTitleFontSize: 9,
    });

    // Right insight panel
    const px = 6.3;
    s.addShape(pres.shapes.RECTANGLE, {
      x: px, y: 0.85, w: 3.35, h: 4.42,
      fill: { color: C.white }, line: { color: C.ltGray, width: 1 },
      shadow: mkShadow()
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: px, y: 0.85, w: 3.35, h: 0.42,
      fill: { color: C.navy }, line: { color: C.navy }
    });
    s.addText("WHY THE DIFFERENCE?", {
      x: px + 0.1, y: 0.85, w: 3.15, h: 0.42,
      fontSize: 11, bold: true, color: C.white, fontFace: "Calibri",
      align: "center", valign: "middle", margin: 0
    });

    const insights = [
      { icon: "🟢", head: "Low-carbon leaders", body: "France, UK, Portugal rely heavily on nuclear and/or renewables for electricity — keeping per capita emissions at 3.5–4.5 t." },
      { icon: "🟡", head: "EU average", body: "The EU-27 as a whole (6 t) reflects a mix — with cleaner western members offset by coal-heavy eastern members." },
      { icon: "🔴", head: "Higher emitters", body: "Germany, Netherlands, and the US still rely more on fossil fuels — resulting in 8–14 t per person." },
    ];

    insights.forEach((item, i) => {
      const iy = 1.42 + i * 1.25;
      s.addShape(pres.shapes.RECTANGLE, {
        x: px + 0.12, y: iy, w: 3.11, h: 1.12,
        fill: { color: C.offWht }, line: { color: C.ltGray, width: 0.5 }
      });
      s.addText(item.head, {
        x: px + 0.22, y: iy + 0.05, w: 3.0, h: 0.3,
        fontSize: 11, bold: true, color: C.charcoal, fontFace: "Calibri",
        align: "left", margin: 0
      });
      s.addText(item.body, {
        x: px + 0.22, y: iy + 0.33, w: 3.0, h: 0.75,
        fontSize: 9.5, color: C.charcoal, fontFace: "Calibri",
        align: "left", valign: "top", margin: 0
      });
    });

    s.addText("Key lesson: similar prosperity levels can yield very different emissions\ndepending on energy policy choices.", {
      x: px + 0.12, y: 4.58 + (0.85 - 0.35), w: 3.11, h: 0.4,
      fontSize: 9, color: C.midGray, fontFace: "Calibri", italic: true,
      align: "center", margin: 0
    });
  }

  // ── SLIDE 9 – Key Takeaways ───────────────────────────────────────────────
  {
    const s = pres.addSlide();
    s.background = { color: C.dark };
    addFooter(s, pres);

    // Footer on dark slide needs different color
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 5.42, w: 10, h: 0.205,
      fill: { color: "1A2E44" }, line: { color: "1A2E44" }
    });
    s.addText("Source: Global Carbon Budget 2025 via Our World in Data  |  ourworldindata.org/co2-emissions", {
      x: 0.3, y: 5.42, w: 9.4, h: 0.205,
      fontSize: 8, color: "4A6A8A", fontFace: "Calibri",
      valign: "middle", align: "left", margin: 0
    });

    s.addText("Key Takeaways", {
      x: 0.55, y: 0.22, w: 8.9, h: 0.62,
      fontSize: 30, bold: true, color: C.white, fontFace: "Calibri",
      align: "left", valign: "middle", margin: 0
    });
    s.addText("Responsibility Is Shared but Unequal", {
      x: 0.55, y: 0.82, w: 8.9, h: 0.35,
      fontSize: 16, color: C.tealLt, fontFace: "Calibri",
      italic: true, align: "left", margin: 0
    });

    const takeaways = [
      {
        num: "01",
        head: "Emissions still rising — no peak yet",
        body: "Global CO₂ exceeds 35 Bt/yr. Growth has slowed but not reversed.",
        accent: C.red
      },
      {
        num: "02",
        head: "China leads total; US leads per capita among large nations",
        body: "China emits 31% of global CO₂ but only ~9 t/person, well below the US (~14 t).",
        accent: C.teal
      },
      {
        num: "03",
        head: "Historical responsibility skewed toward Europe and the US",
        body: "They dominated emissions for over a century (>90% in 1900) before Asia's rise.",
        accent: "2E86C1"
      },
      {
        num: "04",
        head: "Per capita inequality is extreme: a 150× gap",
        body: "The average American emits in <2 days what a Chadian emits in a year.",
        accent: C.amber
      },
      {
        num: "05",
        head: "Energy policy can decouple prosperity from emissions",
        body: "France and the UK prove clean-energy economies are possible at high living standards.",
        accent: C.tealLt
      },
    ];

    const cardW = 1.72, cardH = 3.6;
    const startX = 0.35, cardY = 1.32;
    const gap = 0.07;

    takeaways.forEach((t, i) => {
      const cx = startX + i * (cardW + gap);
      s.addShape(pres.shapes.RECTANGLE, {
        x: cx, y: cardY, w: cardW, h: cardH,
        fill: { color: "0D2040" }, line: { color: t.accent, width: 1.5 }
      });
      // top accent bar
      s.addShape(pres.shapes.RECTANGLE, {
        x: cx, y: cardY, w: cardW, h: 0.06,
        fill: { color: t.accent }, line: { color: t.accent }
      });
      // number
      s.addText(t.num, {
        x: cx + 0.1, y: cardY + 0.12, w: cardW - 0.2, h: 0.55,
        fontSize: 26, bold: true, color: t.accent, fontFace: "Calibri",
        align: "left", margin: 0
      });
      // heading
      s.addText(t.head, {
        x: cx + 0.1, y: cardY + 0.68, w: cardW - 0.2, h: 1.3,
        fontSize: 11, bold: true, color: C.white, fontFace: "Calibri",
        align: "left", valign: "top", margin: 0
      });
      // body
      s.addText(t.body, {
        x: cx + 0.1, y: cardY + 2.05, w: cardW - 0.2, h: 1.4,
        fontSize: 9.5, color: "9BBCD6", fontFace: "Calibri",
        align: "left", valign: "top", margin: 0
      });
    });
  }

  await pres.writeFile({ fileName: OUT });
  console.log("Saved:", OUT);
}

buildDeck().catch(err => { console.error(err); process.exit(1); });

