"use strict";
const pptxgen = require("pptxgenjs");
const path = require("path");

const ASSETS = "/app/benchmark/assets";
const OUT = "/app/output/final_deck.pptx";

// ── Palette ────────────────────────────────────────────────────────────────
// Deep-ocean climate theme
const C = {
  dark:   "0A1628",   // near-black navy  – title/conclusion bg
  navy:   "0D2B55",   // slide header bar
  teal:   "0D7377",   // accent / bars
  tealLt: "14A09C",   // lighter teal
  amber:  "E8A020",   // warm highlight
  red:    "C0392B",   // warning / rise
  blue:   "2E86C1",   // decrease
  white:  "FFFFFF",
  offWht: "F4F7FB",
  ltGray: "E2E8F0",
  midGray:"64748B",
  charcoal:"1E2A3A",
};

// ── Helper: shadow factory (fresh object each call) ────────────────────────
const mkShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.12 });

// ── Helper: slide header bar ───────────────────────────────────────────────
function addHeader(slide, pres, title, dark = false) {
  const bg = dark ? C.dark : C.navy;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.72,
    fill: { color: bg }, line: { color: bg }
  });
  slide.addText(title, {
    x: 0.35, y: 0, w: 9.3, h: 0.72,
    fontSize: 20, bold: true, color: C.white,
    fontFace: "Calibri", valign: "middle", align: "left", margin: 0
  });
}

// ── Helper: source footer ──────────────────────────────────────────────────
function addFooter(slide, pres) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.42, w: 10, h: 0.205,
    fill: { color: C.ltGray }, line: { color: C.ltGray }
  });
  slide.addText("Source: Global Carbon Budget 2025 via Our World in Data  |  ourworldindata.org/co2-emissions", {
    x: 0.3, y: 5.42, w: 9.4, h: 0.205,
    fontSize: 8, color: C.midGray, fontFace: "Calibri",
    valign: "middle", align: "left", margin: 0
  });
}

// ── Helper: stat callout box ───────────────────────────────────────────────
function addStatBox(slide, pres, stat, label, x, y, w, h, accentColor) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w, h,
    fill: { color: C.offWht }, line: { color: C.ltGray, width: 1 },
    shadow: mkShadow()
  });
  // left accent strip
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w: 0.06, h,
    fill: { color: accentColor || C.teal }, line: { color: accentColor || C.teal }
  });
  slide.addText(stat, {
    x: x + 0.14, y: y + 0.05, w: w - 0.2, h: h * 0.55,
    fontSize: 28, bold: true, color: C.charcoal, fontFace: "Calibri",
    valign: "middle", align: "left", margin: 0
  });
  slide.addText(label, {
    x: x + 0.14, y: y + h * 0.55, w: w - 0.2, h: h * 0.42,
    fontSize: 10, color: C.midGray, fontFace: "Calibri",
    valign: "top", align: "left", margin: 0
  });
}

// ══════════════════════════════════════════════════════════════════════════
async function buildDeck() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Global Carbon Budget 2025 / Our World in Data";
  pres.title  = "Global CO₂ Emissions: Who Emits, How Much, and What's Changing";

  // ── SLIDE 1 – Title ──────────────────────────────────────────────────────
  {
    const s = pres.addSlide();
    s.background = { color: C.dark };

    // Decorative teal band
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 3.6, w: 10, h: 0.06,
      fill: { color: C.teal }, line: { color: C.teal }
    });
    // amber accent line
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 3.66, w: 10, h: 0.03,
      fill: { color: C.amber }, line: { color: C.amber }
    });

    s.addText("Global CO₂ Emissions", {
      x: 0.7, y: 0.7, w: 8.6, h: 1.1,
      fontSize: 44, bold: true, color: C.white,
      fontFace: "Calibri", align: "left", valign: "bottom", margin: 0
    });
    s.addText("Who Emits, How Much, and What's Changing", {
      x: 0.7, y: 1.75, w: 8.6, h: 0.75,
      fontSize: 26, bold: false, color: C.tealLt,
      fontFace: "Calibri", align: "left", valign: "top", margin: 0
    });
    s.addText("Fossil fuels & industry  ·  1750–2024", {
      x: 0.7, y: 2.65, w: 8.6, h: 0.45,
      fontSize: 15, color: "9BBCD6", fontFace: "Calibri",
      align: "left", margin: 0
    });

    s.addText([
      { text: "Data: ", options: { bold: true, color: C.amber } },
      { text: "Global Carbon Budget 2025  ·  Our World in Data  ·  ourworldindata.org/co2-emissions", options: { color: "A0B8CC" } }
    ], {
      x: 0.7, y: 3.85, w: 8.6, h: 0.4,
      fontSize: 11, fontFace: "Calibri", align: "left", margin: 0
    });

    s.addText("Prepared for policy analysts, climate negotiators, and sustainability researchers", {
      x: 0.7, y: 4.35, w: 8.6, h: 0.35,
      fontSize: 11, color: C.midGray, fontFace: "Calibri",
      italic: true, align: "left", margin: 0
    });

    // small globe-like decorative circle
    s.addShape(pres.shapes.OVAL, {
      x: 7.8, y: 0.5, w: 1.8, h: 1.8,
      fill: { color: C.teal, transparency: 80 },
      line: { color: C.tealLt, width: 1.5 }
    });
    s.addShape(pres.shapes.OVAL, {
      x: 8.05, y: 0.75, w: 1.3, h: 1.3,
      fill: { color: C.teal, transparency: 60 },
      line: { color: C.teal, width: 0 }
    });
  }

  // ── SLIDE 2 – Global Emissions Growth (area chart) ───────────────────────
  {
    const s = pres.addSlide();
    s.background = { color: C.offWht };
    addHeader(s, pres, "Global CO₂ Emissions Grew from 6 Bt in 1950 to Over 35 Bt Today");
    addFooter(s, pres);

    // Area / Line chart – approximate trajectory data
    const decades = ["1750","1800","1850","1880","1900","1920","1940","1950","1960","1970","1980","1990","2000","2010","2020","2024"];
    const values  = [0.005, 0.04,  0.2,   0.5,   1.0,   2.0,   4.0,   6.0,   9.5,   14.5,  19.0,  22.5,  25.5,  31.5,  34.0,  35.5];

    s.addChart(pres.charts.LINE, [
