// ── Helper: stat callout box ───────────────────────────────────────────────
function addStatBox(slide, pres, stat, label, x, y, w, h, accentColor) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w, h,
    fill: { color: C.offWht }, line: { color: C.ltGray, width: 1 },
    shadow: mkShadow()
  });
  // left accent strip
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w: 0.06, h,
    fill: { color: accentColor || C.teal }, line: { color: accentColor || C.teal }
  });
  slide.addText(stat, {
    x: x + 0.14, y: y + 0.05, w: w - 0.2, h: h * 0.55,
    fontSize: 28, bold: true, color: C.charcoal, fontFace: "Calibri",
    valign: "middle", align: "left", margin: 0
  });
  slide.addText(label, {
    x: x + 0.14, y: y + h * 0.55, w: w - 0.2, h: h * 0.42,
    fontSize: 10, color: C.midGray, fontFace: "Calibri",
    valign: "top", align: "left", margin: 0
  });
}

